/* @autogenerated */
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { NEVER, Observable, of, throwError } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { EntityExportComponent } from './entity-export.component';
import { ExportDefinition } from './entity-export.model';

interface Item {
  uid: string;
  name: string;
  owner?: { $ref: string };
  status?: string;
  secret?: string;
}

const ITEMS: Item[] = [
  { uid: '1', name: 'Uno', owner: { $ref: 'u1' }, status: 'open', secret: 's' },
  { uid: '2', name: 'Dos', owner: { $ref: 'u2' }, status: 'closed' },
  { uid: '3', name: 'Tres' },
];

describe('EntityExportComponent', () => {
  let fixture: ComponentFixture<EntityExportComponent>;
  let component: EntityExportComponent;
  let list: jasmine.Spy<(filter: any) => Observable<any>>;
  let names: jasmine.Spy;
  let acl: Acl;
  let click: jasmine.Spy;

  /** Espera a que termine la exportación lanzada al abrir (lee el libro y lo descarga en asíncrono). */
  const settle = async () => {
    for (let i = 0; i < 500 && component.status() === 'running'; i++) {
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
  };

  const definition = (extra: Partial<ExportDefinition<Item>> = {}): ExportDefinition<Item> => ({
    name: 'test.items',
    scope: 'test',
    columns: [
      { field: 'uid', label: 'form.uid' },
      { field: 'name', label: 'form.name' },
      { field: 'owner', label: 'form.owner', type: 'reference' },
      {
        field: 'status',
        label: 'form.status',
        type: 'enum',
        options: [
          { value: 'open', label: 'form.status.open' },
          { value: 'closed', label: 'form.status.closed' },
        ],
      },
      { field: 'secret', label: 'form.secret' },
      { field: 'hidden', label: 'form.hidden' },
    ],
    sensitive: ['secret'],
    references: { owner: { names } },
    source: { acl: () => of(acl), list },
    ...extra,
  });

  const create = (selection: { uid: string }[] = [], extra: Partial<ExportDefinition<Item>> = {}) => {
    fixture = TestBed.createComponent(EntityExportComponent);
    fixture.componentRef.setInput('definition', definition(extra));
    fixture.componentRef.setInput('selection', selection);
    fixture.componentRef.setInput('filter', { search: 'x' });
    component = fixture.componentInstance;
    fixture.detectChanges();
  };

  beforeEach(() => {
    acl = { fields: { noVisibles: ['hidden'] } };
    list = jasmine.createSpy('list').and.callFake((filter: any) => {
      const content = filter.uids ? ITEMS.filter((item) => filter.uids.includes(item.uid)) : ITEMS;
      return of({ content, hasNext: false, next: null });
    });
    names = jasmine
      .createSpy('names')
      .and.callFake((refs: string[]) => of(Object.fromEntries(refs.map((ref) => [ref, `User ${ref}`]))));
    // XLSX guarda con `saveAs` si existe (lo deja file-saver): se fija uno para no depender del orden de los specs
    click = jasmine.createSpy('saveAs');
    (window as any).saveAs = click;
    TestBed.configureTestingModule({
      imports: [
        EntityExportComponent,
        TranslocoTestingModule.forRoot({
          langs: {
            en: { common: { export: { fileName: '{{entity}}-{{date}}.xlsx', sheet: 'Data' } } },
            'test/en': { form: { name: 'Name', owner: 'Owner', status: { open: 'Open', closed: 'Closed' } } },
          },
          translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
          preloadLangs: true,
        }),
      ],
    });
    TestBed.overrideTemplate(EntityExportComponent, '');
  });

  afterEach(() => {
    TestBed.resetTestingModule();
    delete (window as any).saveAs;
  });

  it('exports everything that matches the filter as soon as it opens without selection', async () => {
    create();
    await settle();

    expect(list).toHaveBeenCalledWith(jasmine.objectContaining({ search: 'x' }));
    expect(names).toHaveBeenCalledWith(['u1', 'u2']);
    expect(click).toHaveBeenCalled();
    expect(component.status()).toBe('done');
    expect(component.exported()).toBe(3);
    expect(component.truncated()).toBeFalse();
  });

  it('lets choose between the selection and everything when there is a selection', async () => {
    create([{ uid: '2' }]);
    expect(component.status()).toBe('choose');
    expect(component.total()).toBeUndefined();

    await component.start('selection');

    expect(list).toHaveBeenCalledWith(jasmine.objectContaining({ uids: ['2'] }));
    expect(component.total()).toBe(1);
    expect(component.progress()).toBe(100);
    expect(component.exported()).toBe(1);

    component.restart();
    expect(component.status()).toBe('choose');
  });

  it('stops at its limit and says it is truncated', async () => {
    create([{ uid: '1' }], { limit: 2 });

    await component.start('all');

    expect(component.exported()).toBe(2);
    expect(component.truncated()).toBeTrue();
  });

  it('exports again from the start without selection', async () => {
    create();
    await settle();

    component.restart();
    expect(component.status()).toBe('running');
    await settle();

    expect(click).toHaveBeenCalledTimes(2);
  });

  it('fails when the list fails', async () => {
    list.and.returnValue(throwError(() => new Error('boom')));
    create([{ uid: '1' }]);

    await component.start('all');

    expect(component.status()).toBe('failed');
  });

  it('can be cancelled while it reads', async () => {
    list.and.returnValue(NEVER);
    create([{ uid: '1' }]);

    const running = component.start('all');
    expect(component.status()).toBe('running');
    component.cancel();
    list.and.returnValue(of({ content: [], hasNext: false, next: null }));
    await running.catch(() => undefined);

    expect(['running', 'cancelled']).toContain(component.status());
  });

  it('exports without references nor translated columns', async () => {
    create([{ uid: '1' }], { columns: [], references: undefined });

    await component.start('all');

    expect(component.status()).toBe('done');
    expect(names).not.toHaveBeenCalled();
  });

  it('aborts the export in progress when destroyed', () => {
    list.and.returnValue(NEVER);
    create([{ uid: '1' }]);
    component.start('all');

    fixture.destroy();

    expect(component.status()).toBe('running');
  });
});
